<section class="panel"><div class="mb-4 flex items-center justify-between"><div><h2 class="section-title">Detalle</h2><p class="mt-1 text-xs text-muted">Cada línea es editable. Los conceptos quedan disponibles para futuras sugerencias.</p></div><button type="button" class="button-secondary" @click="addItem">＋ Agregar línea</button></div><div class="overflow-x-auto rounded-xl border border-line"><table class="w-full min-w-[1040px] text-left text-sm"><thead class="bg-surface-soft"><tr class="text-[11px] font-bold uppercase tracking-[0.12em] text-muted"><th class="w-[22%] px-3 py-3">Concepto</th><th class="w-[27%] px-3 py-3">Descripción</th><th class="w-24 px-3 py-3">Cantidad</th><th class="w-28 px-3 py-3">Unidad</th><th class="w-32 px-3 py-3">Precio unit.</th><th class="w-28 px-3 py-3">Descuento</th><th class="w-24 px-3 py-3">Imp. %</th><th class="w-32 px-3 py-3 text-right">Total</th><th class="w-10 px-2 py-3"></th></tr></thead><tbody class="divide-y divide-line/70"><template x-for="(item,index) in items" :key="index"><tr class="align-top hover:bg-surface-soft/60"><td class="p-2"><input class="input mt-0 min-h-10 border-line bg-surface px-2 focus:border-brand" :name="`items[${index}][concept]`" x-model="item.concept" required></td><td class="p-2"><input class="input mt-0 min-h-10 border-line bg-surface px-2 focus:border-brand" :name="`items[${index}][description]`" x-model="item.description"></td><td class="p-2"><input class="input mt-0 min-h-10 border-line bg-surface px-2" type="number" step="0.01" min="0.01" :name="`items[${index}][quantity]`" x-model.number="item.quantity" required></td><td class="p-2"><input class="input mt-0 min-h-10 border-line bg-surface px-2" :name="`items[${index}][unit]`" x-model="item.unit" required></td><td class="p-2"><input class="input mt-0 min-h-10 border-line bg-surface px-2" type="number" step="0.01" min="0" :name="`items[${index}][unit_price]`" x-model.number="item.unit_price" required></td><td class="p-2"><input class="input mt-0 min-h-10 border-line bg-surface px-2" type="number" step="0.01" min="0" :name="`items[${index}][discount]`" x-model.number="item.discount"></td><td class="p-2"><input class="input mt-0 min-h-10 border-line bg-surface px-2" type="number" step="0.01" min="0" max="100" :name="`items[${index}][tax_rate]`" x-model.number="item.tax_rate"></td><td class="p-3 text-right"><span class="font-black text-ink" x-text="money(lineTotal(item))"></span></td><td class="p-3 text-center"><button type="button" class="text-xl font-bold text-red-600" @click="removeItem(index)" aria-label="Eliminar línea">×</button></td></tr></template></tbody></table></div><div class="mt-5 ml-auto max-w-sm space-y-2 border-t border-line pt-4 text-sm"><div class="flex justify-between"><span class="text-muted">Subtotal</span><strong x-text="money(subtotal)"></strong></div><div class="flex justify-between"><span class="text-muted">Descuento</span><strong x-text="money(discount)"></strong></div><div class="flex justify-between"><span class="text-muted">Impuestos</span><strong x-text="money(taxTotal)"></strong></div><div class="flex justify-between text-lg"><span class="font-black">Total</span><strong class="text-brand" x-text="money(total)"></strong></div></div></section>
