<script>function commercialEditor(initial){return {items:initial.map(i=>({concept:i.concept||'',description:i.description||'',quantity:Number(i.quantity||1),unit:i.unit||'unidad',unit_price:Number(i.unit_price||0),discount:Number(i.discount||0),tax_rate:Number(i.tax_rate||0)})),discount:Number(@js(old('discount',$document->discount??0))),addItem(){this.items.push({concept:'',description:'',quantity:1,unit:'unidad',unit_price:0,discount:0,tax_rate:0})},removeItem(i){if(this.items.length>1)this.items.splice(i,1)},lineTotal(i){let s=Math.max(0,i.quantity*i.unit_price-i.discount);return s*(1+i.tax_rate/100)},get subtotal(){return this.items.reduce((s,i)=>s+Math.max(0,i.quantity*i.unit_price-i.discount),0)},get taxTotal(){return this.items.reduce((s,i)=>s+Math.max(0,i.quantity*i.unit_price-i.discount)*i.tax_rate/100,0)},get total(){return Math.max(0,this.subtotal-this.discount+this.taxTotal)},money(v){return new Intl.NumberFormat('es-DO',{style:'currency',currency:'USD'}).format(v)}}}</script>
